mapper.select:
select pcp.Pcp_File_Name as pcpFileName, pcp.Pcp_Year as pcpYear, pcp.Pcp_Create_Uname as pcpCreateUname, pcp.Pcp_State as pcpState, c1.C_Name as cplAgencyName, c2.C_Name as cplLiableCompanyName, dp1.D_Name as cplDeclareDepName, dp2.D_Name as cplUseDepName, mn.* from Pro_Construction_Plan_List mn left join Pro_Construction_Plan pcp on pcp.Pcp_Id=mn.Pcp_Id left join SYS_Company c1 on c1.C_Id=mn.Cpl_Agency left join SYS_Company c2 on c2.C_Id=mn.Cpl_Liable_Company left join SYS_Department dp1 on dp1.D_Id=mn.Cpl_Declare_Dep left join SYS_Department dp2 on dp2.D_Id=mn.Cpl_Use_Dep where 1=1
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Cpl_Create_Time DESC
